import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import { browserDirectRFBAuthentication } from "../src/app/rfb/browser-auth.ts";

test("browser direct auth caches successful prompted credentials per tab", async () => {
  const values = new Map<string, string>();
  const storage = {
    getItem: (key: string) => values.get(key) ?? null,
    setItem: (key: string, value: string) => void values.set(key, value),
    removeItem: (key: string) => void values.delete(key),
  };
  const first = await browserDirectRFBAuthentication(
    "test-host",
    storage,
    () => "test-ownership-token-1",
  );
  first.onVNCAuthentication(true);

  const second = await browserDirectRFBAuthentication("test-host", storage, () => {
    throw new Error("cached password should avoid prompting");
  });
  assert.equal(second.password, "test-ownership-token-1");
  second.onVNCAuthentication(false);
  assert.equal(values.size, 0);
});

test("browser direct auth treats unavailable session storage as best effort", async () => {
  const storage = {
    getItem: () => {
      throw new DOMException("blocked", "SecurityError");
    },
    setItem: () => {
      throw new DOMException("full", "QuotaExceededError");
    },
    removeItem: () => {
      throw new DOMException("blocked", "SecurityError");
    },
  };
  const authentication = await browserDirectRFBAuthentication(
    "test-host",
    storage,
    () => "test-ownership-token-1",
  );

  assert.equal(authentication.password, "test-ownership-token-1");
  assert.doesNotThrow(() => authentication.onVNCAuthentication(true));
  assert.doesNotThrow(() => authentication.onVNCAuthentication(false));

  const noStorage = await browserDirectRFBAuthentication(
    "test-host",
    null,
    () => "test-ownership-token-2",
  );
  assert.equal(noStorage.password, "test-ownership-token-2");
  assert.doesNotThrow(() => noStorage.onVNCAuthentication(true));
});

test("browser share code field avoids account-password autofill", async () => {
  const source = await readFile(new URL("../src/app/desktop-viewer.jsx", import.meta.url), "utf8");
  const prompt = source.slice(source.indexOf("export function requestBrowserRFBPassword"));

  assert.match(prompt, /input\.type = "password"/);
  assert.match(prompt, /input\.autocomplete = "one-time-code"/);
  assert.match(prompt, /input\.setAttribute\("autocapitalize", "none"\)/);
  assert.match(prompt, /input\.setAttribute\("autocorrect", "off"\)/);
  assert.match(prompt, /input\.spellcheck = false/);
  assert.doesNotMatch(prompt, /current-password/);
});

export type BrowserRFBAuthenticationOptions = {
  password: string;
  onVNCAuthentication(succeeded: boolean): void;
};

// The project's tsconfig does not pull in the DOM lib for this module, so the
// storage surface is described structurally rather than via the DOM `Storage`.
interface BrowserCredentialStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export async function browserDirectRFBAuthentication(
  hostID: string,
  storage: BrowserCredentialStorage | null,
  promptForPassword: () => string | null | Promise<string | null>,
): Promise<BrowserRFBAuthenticationOptions> {
  const key = `crabfleet.rfb.password.${hostID}`;
  let saved: string | null = null;
  try {
    saved = storage?.getItem(key) ?? null;
  } catch {
    // Private browsing and browser policy may make sessionStorage unavailable.
  }
  const password = saved ?? (await promptForPassword());
  if (password === null) throw new Error("RFB password entry cancelled");
  return {
    password,
    onVNCAuthentication(succeeded) {
      try {
        if (succeeded) storage?.setItem(key, password);
        else storage?.removeItem(key);
      } catch {
        // Authentication remains valid even when tab-scoped caching is unavailable.
      }
    },
  };
}

use super::*;
use std::{cell::RefCell, rc::Rc};
use wasm_bindgen::{JsCast, JsValue};
use wasm_bindgen_futures::{JsFuture, spawn_local};
use web_sys::{
    AbortController, ReadableStreamDefaultReader, ReferrerPolicy, Request, RequestCache,
    RequestCredentials, RequestInit, RequestMode, RequestRedirect, Response,
};

type ResultCell = Rc<RefCell<Option<Result<Outcome, Error>>>>;
pub struct AuthTask {
    result: Option<ResultCell>,
    abort: AbortController,
    started_ms: u64,
}
impl AuthTask {
    pub fn start(credentials: Credentials, now_ms: u64) -> Result<Self, Error> {
        credentials.validate()?;
        let body = Zeroizing::new(
            serde_json::to_vec(&credentials)
                .map_err(|_| Error("Could not encode account request"))?,
        );
        drop(credentials);
        let abort =
            AbortController::new().map_err(|_| Error("Browser cancellation is unavailable"))?;
        let init = RequestInit::new();
        init.set_method("POST");
        init.set_mode(RequestMode::SameOrigin);
        // Inheriting no-referrer makes Firefox send Origin: null on this POST.
        init.set_referrer_policy(ReferrerPolicy::SameOrigin);
        init.set_credentials(RequestCredentials::Omit);
        init.set_redirect(RequestRedirect::Error);
        init.set_cache(RequestCache::NoStore);
        init.set_signal(Some(&abort.signal()));
        let body_text = std::str::from_utf8(&body).map_err(|_| Error("Invalid sign-in request"))?;
        init.set_body(&JsValue::from_str(body_text));
        let request = Request::new_with_str_and_init(
            &crate::gateway_url(crate::GATEWAY_AUTH_PATH, false)?,
            &init,
        )
        .map_err(|_| Error("Could not create account request"))?;
        request
            .headers()
            .set("Content-Type", "application/json")
            .map_err(|_| Error("Could not set account request headers"))?;
        request
            .headers()
            .set("Accept", "application/json")
            .map_err(|_| Error("Could not set account request headers"))?;
        let promise = web_sys::window()
            .ok_or(Error("Browser window is unavailable"))?
            .fetch_with_request(&request);
        let result = Rc::new(RefCell::new(None));
        let weak = Rc::downgrade(&result);
        let cancel = abort.clone();
        spawn_local(async move {
            let outcome = read_response(promise).await;
            if outcome.is_err() {
                cancel.abort();
            }
            if let Some(result) = weak.upgrade() {
                *result.borrow_mut() = Some(outcome);
            }
        });
        Ok(Self {
            result: Some(result),
            abort,
            started_ms: now_ms,
        })
    }
    pub fn poll(&mut self, now_ms: u64) -> Option<Result<Outcome, Error>> {
        let outcome = self.result.as_ref()?.borrow_mut().take();
        if outcome.is_some() {
            self.result = None;
            return outcome;
        }
        if now_ms.saturating_sub(self.started_ms) > TIMEOUT_MS {
            self.cancel();
            return Some(Err(Error("Account sign-in timed out")));
        }
        None
    }
    pub fn cancel(&mut self) {
        self.result = None;
        self.abort.abort();
    }
}
impl Drop for AuthTask {
    fn drop(&mut self) {
        self.cancel();
    }
}

async fn read_response(promise: js_sys::Promise) -> Result<Outcome, Error> {
    let response: Response = JsFuture::from(promise)
        .await
        .map_err(|_| Error("Could not reach the web gateway"))?
        .dyn_into()
        .map_err(|_| Error("Invalid browser account response"))?;
    if response.status() == 429 {
        return Err(Error("The web gateway is busy; try again shortly"));
    }
    if response.status() >= 500 {
        return Err(Error("The web gateway could not reach the account service"));
    }
    if matches!(response.status(), 404 | 405) {
        return Err(Error("Open the viewer through crabfleet-web-gateway"));
    }
    if response
        .headers()
        .get("Content-Length")
        .ok()
        .flatten()
        .and_then(|value| value.parse::<usize>().ok())
        .is_some_and(|length| length > MAX_RESPONSE_BYTES)
    {
        return Err(Error("Sign-in response exceeds the client limit"));
    }
    let reader: ReadableStreamDefaultReader = response
        .body()
        .ok_or(Error("Account response has no body"))?
        .get_reader()
        .dyn_into()
        .map_err(|_| Error("Could not read account response stream"))?;
    let mut bytes = Zeroizing::new(Vec::new());
    loop {
        let next = JsFuture::from(reader.read())
            .await
            .map_err(|_| Error("Could not read account response"))?;
        let done = js_sys::Reflect::get(&next, &JsValue::from_str("done"))
            .map_err(|_| Error("Invalid response stream"))?
            .as_bool()
            .unwrap_or(false);
        if done {
            break;
        }
        let value = js_sys::Reflect::get(&next, &JsValue::from_str("value"))
            .map_err(|_| Error("Invalid response stream"))?;
        let chunk: js_sys::Uint8Array = value
            .dyn_into()
            .map_err(|_| Error("Invalid response stream chunk"))?;
        if chunk.length() as usize > MAX_RESPONSE_BYTES.saturating_sub(bytes.len()) {
            return Err(Error("Sign-in response exceeds the client limit"));
        }
        bytes.extend_from_slice(&chunk.to_vec());
    }
    reader.release_lock();
    parse_response(response.status(), &bytes)
}

import assert from "node:assert/strict";
import test from "node:test";

import { vncChallengeResponse } from "../src/app/rfb/vnc-auth.ts";

test("browser VNC DES matches the RoyalVNCKit compatibility vector", () => {
  const challenge = new Uint8Array(Array.from({ length: 16 }, (_, index) => index));
  assert.deepEqual(
    vncChallengeResponse(challenge, "test-auth-token"),
    Uint8Array.from([
      0x8a, 0x5f, 0xa9, 0x58, 0xf0, 0xd8, 0x19, 0xbd, 0xcb, 0x98, 0x1c, 0x9b, 0x47, 0x63, 0x6e,
      0xd0,
    ]),
  );
});

test("browser VNC DES enforces challenge and ISO-8859-1 bounds", () => {
  assert.throws(() => vncChallengeResponse(new Uint8Array(15), "test-auth-token"), /16 bytes/);
  assert.throws(() => vncChallengeResponse(new Uint8Array(16), "snowman-☃"), /ISO-8859-1/);
  assert.deepEqual(
    vncChallengeResponse(new Uint8Array(16), "12345678ignored"),
    vncChallengeResponse(new Uint8Array(16), "12345678"),
  );
});

import assert from "node:assert/strict";
import test from "node:test";

import { handlePublicAuthRoute } from "../src/worker/routes/auth.ts";

test("native-link path rejects malformed percent encoding", async () => {
  let called = false;
  await assert.rejects(
    () =>
      handlePublicAuthRoute(
        new Request("https://fleet.example/native/link/%"),
        new URL("https://fleet.example/native/link/%"),
        { kind: "disabled" },
        {
          githubLogin: async () => new Response(),
          githubCallback: async () => new Response(),
          nativeLink: async () => {
            called = true;
            return new Response();
          },
          tokenLogin: async () => new Response(),
          devIdentityLogin: async () => new Response(),
          logout: async () => new Response(),
          authState: () => new Response(),
        },
      ),
    (error: unknown) => {
      assert.equal((error as { status?: number }).status, 400);
      return true;
    },
  );
  assert.equal(called, false);
});

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import {
  actor,
  authMethods,
  authorize,
  bootstrapSubject,
  createSession,
  devIdentityLogin,
  devIdentityId,
  logout,
  parseRole,
  reauthorizeStoredUser,
  requireRole,
  requireUser,
  sessionGitHubToken,
  tokenLogin,
  trustedProxyAutomaticRole,
} from "../src/worker/auth.ts";
import { openSecret, sealSecret, sha256 } from "../src/worker/crypto.ts";
import type { RuntimeEnv } from "../src/worker/env.ts";
import type { User } from "../src/worker/models.ts";

type D1Result = { results?: unknown[]; changes?: number };
type D1Handler = (sql: string, parameters: unknown[], kind: "all" | "run") => D1Result;

function d1(handler: D1Handler): D1Database {
  return {
    prepare(sql: string) {
      return {
        bind(...parameters: unknown[]) {
          return {
            async all() {
              const result = handler(sql, parameters, "all");
              return { results: result.results ?? [], meta: { changes: result.changes ?? 0 } };
            },
            async run() {
              const result = handler(sql, parameters, "run");
              return { meta: { changes: result.changes ?? 0 } };
            },
          };
        },
      };
    },
  } as unknown as D1Database;
}

function runtimeEnv(db: D1Database, values: Partial<RuntimeEnv> = {}): RuntimeEnv {
  return { DB: db, ...values } as RuntimeEnv;
}

function user(values: Partial<User> = {}): User {
  return {
    subject: "github:42",
    login: "owner",
    email: "owner@example.com",
    name: "Owner",
    role: "viewer",
    allowed: false,
    teams: ["@openclaw/core"],
    ...values,
  };
}

test("allowlist authorization selects the strongest matching identity role", async () => {
  const env = runtimeEnv(
    d1((sql) => {
      assert.match(sql, /from "allow_entries"/i);
      return {
        results: [
          { value: "@owner", role: "viewer" },
          { value: "owner@example.com", role: "maintainer" },
          { value: "@openclaw/core", role: "owner" },
          { value: "@someone-else", role: "owner" },
        ],
      };
    }),
  );

  assert.deepEqual(await authorize(env, user()), { ...user(), role: "owner", allowed: true });
});

test("development sessions are invalidated when the local login gate is unavailable", async () => {
  let deletedTokenHash: unknown;
  const token = "[REDACTED]";
  const env = runtimeEnv(
    d1((sql, parameters, kind) => {
      if (kind === "all" && /from "sessions" as "s"/i.test(sql)) {
        return {
          results: [
            {
              subject: "dev:operator",
              login: "operator",
              email: null,
              name: "Operator",
              role: "owner",
              allowed: 1,
              teams: "[]",
            },
          ],
        };
      }
      if (kind === "run" && /^delete from "sessions"/i.test(sql)) {
        deletedTokenHash = parameters[0];
        return { changes: 1 };
      }
      throw new Error(`unexpected query: ${sql}`);
    }),
    { CRABFLEET_DEV_LOGIN_ENABLED: "false" },
  );

  await assert.rejects(
    requireUser(
      new Request("https://fleet.example/api/session", {
        headers: { cookie: `crabbox_session=${token}` },
      }),
      env,
      { kind: "disabled" },
    ),
    (error: unknown) =>
      error instanceof Error &&
      error.message === "unauthorized" &&
      "status" in error &&
      error.status === 401,
  );
  assert.equal(deletedTokenHash, await sha256(token));
});

test("stored users are rejected when their source authentication is disabled", async () => {
  const env = runtimeEnv({} as D1Database);
  for (const subject of ["dev:operator", "github:42", "proxy:operator@example.com"]) {
    await assert.rejects(
      reauthorizeStoredUser(env, user({ subject, allowed: true })),
      (error: unknown) =>
        error instanceof Error &&
        "status" in error &&
        error.status === 403 &&
        /no longer|cannot authorize/.test(error.message),
    );
  }
  await assert.rejects(
    reauthorizeStoredUser(
      runtimeEnv({} as D1Database, { CRABFLEET_DEV_LOGIN_ENABLED: "true" }),
      user({ subject: "dev:operator", allowed: true }),
    ),
    (error: unknown) =>
      error instanceof Error &&
      "status" in error &&
      error.status === 403 &&
      /cannot authorize stored clients/.test(error.message),
  );
});

test("session GitHub credentials are bound to the authenticated subject", async () => {
  const token = "[REDACTED]";
  const secretEnv = runtimeEnv({} as D1Database, {
    CRABBOX_TOKEN_ENCRYPTION_KEY: "encryption-key",
  });
  const ciphertext = await sealSecret(secretEnv, "github-token");
  assert.ok(ciphertext);

  const env = runtimeEnv(
    d1((sql, parameters) => {
      assert.match(sql, /from "sessions"/i);
      assert.match(sql, /"subject" = \?/i);
      return parameters.includes("github:42")
        ? { results: [{ github_token_ciphertext: ciphertext }] }
        : { results: [] };
    }),
    { CRABBOX_TOKEN_ENCRYPTION_KEY: "encryption-key" },
  );
  const request = new Request("https://fleet.example/api/session", {
    headers: { cookie: `crabbox_session=${token}` },
  });

  assert.equal(await sessionGitHubToken(request, env, "github:42"), "github-token");
  assert.equal(await sessionGitHubToken(request, env, "proxy:owner@example.com"), undefined);
});

test("session creation and logout persist only hashed browser tokens", async () => {
  const writes: Array<{ sql: string; parameters: unknown[] }> = [];
  const env = runtimeEnv(
    d1((sql, parameters, kind) => {
      if (kind === "run") writes.push({ sql, parameters });
      return { changes: 1 };
    }),
    { CRABBOX_TOKEN_ENCRYPTION_KEY: "encryption-key" },
  );
  const request = new Request("https://fleet.example/api/session");
  const session = await createSession(env, request, "github:42", 1_000, 900, "github-token");
  const cookieValue = session.match(/^crabbox_session=([^;]+)/)?.[1];
  assert.ok(cookieValue);
  assert.equal(writes.length, 2);
  assert.match(writes[0]?.sql ?? "", /^delete from "sessions"/i);
  assert.match(writes[1]?.sql ?? "", /^insert into "sessions"/i);
  assert.equal(writes[1]?.parameters.includes(cookieValue), false);
  assert.ok(writes[1]?.parameters.includes(await sha256(decodeURIComponent(cookieValue))));

  const response = await logout(
    new Request("https://fleet.example/api/logout", {
      headers: { cookie: `crabbox_session=${cookieValue}` },
    }),
    env,
  );
  assert.equal(response.status, 200);
  assert.match(response.headers.get("set-cookie") ?? "", /Max-Age=0/);
  assert.match(writes.at(-1)?.sql ?? "", /^delete from "sessions"/i);
});

test("bootstrap and development login handlers own their validation and sessions", async () => {
  const writes: string[] = [];
  const env = runtimeEnv(
    d1((sql, _parameters, kind) => {
      if (kind === "run") writes.push(sql);
      return { changes: 1 };
    }),
    {
      CRABBOX_BOOTSTRAP_TOKEN: "bootstrap",
      CRABFLEET_DEV_LOGIN_ENABLED: "true",
    },
  );
  const invalid = await tokenLogin(
    new Request("https://fleet.example/api/login/token", {
      method: "POST",
      body: JSON.stringify({ token: "wrong" }),
    }),
    env,
  );
  assert.equal(invalid.status, 401);
  assert.equal(writes.length, 0);

  const bootstrap = await tokenLogin(
    new Request("https://fleet.example/api/login/token", {
      method: "POST",
      body: JSON.stringify({ token: "bootstrap" }),
    }),
    env,
  );
  assert.equal(bootstrap.status, 200);
  assert.match(bootstrap.headers.get("set-cookie") ?? "", /^crabbox_session=/);
  assert.equal(
    (await bootstrap.json<{ user: User }>()).user.subject.startsWith("bootstrap:"),
    true,
  );

  const development = await devIdentityLogin(
    new Request("http://127.0.0.1:8787/api/login/dev", {
      method: "POST",
      body: JSON.stringify({ id: " Jane Doe ", name: "Jane", role: "maintainer" }),
    }),
    env,
  );
  assert.equal(development.status, 200);
  assert.deepEqual((await development.json<{ user: User }>()).user, {
    subject: "dev:jane-doe",
    login: "jane-doe",
    email: null,
    name: "Jane",
    role: "maintainer",
    allowed: true,
    teams: [],
  });
  assert.ok(writes.some((sql) => /^insert into "users"/i.test(sql)));
  assert.ok(writes.some((sql) => /^insert into "sessions"/i.test(sql)));
});

test("development login is hidden outside its explicit local gate", async () => {
  const response = await devIdentityLogin(
    new Request("https://fleet.example/api/login/dev", {
      method: "POST",
      body: JSON.stringify({ id: "owner" }),
    }),
    runtimeEnv({} as D1Database, { CRABFLEET_DEV_LOGIN_ENABLED: "true" }),
  );

  assert.equal(response.status, 404);
});

test("auth policy helpers normalize identities, advertise configured methods, and enforce roles", async () => {
  assert.equal(devIdentityId(" DEV:Jane Doe "), "jane-doe");
  assert.equal(devIdentityId("***"), "dev");
  assert.equal(parseRole("maintainer"), "maintainer");
  assert.equal(parseRole("invalid"), "owner");
  assert.equal(actor(user({ login: null })), "owner@example.com");

  const configured = runtimeEnv({} as D1Database, {
    CRABBOX_BOOTSTRAP_TOKEN: "bootstrap",
    GITHUB_CLIENT_ID: "client",
    GITHUB_CLIENT_SECRET: "secret",
    CRABFLEET_DEV_LOGIN_ENABLED: "true",
    CRABFLEET_TRUSTED_PROXY_ORIGIN: "https://backend.example",
    CRABFLEET_TRUSTED_PROXY_SECRET: "[REDACTED]",
  });
  assert.deepEqual(authMethods(configured, new Request("http://127.0.0.1:8787/api/auth/config")), {
    github: true,
    token: true,
    devIdentity: true,
    trustedProxy: true,
  });
  assert.match(await bootstrapSubject(configured), /^bootstrap:[a-f0-9]{24}$/);

  assert.doesNotThrow(() => requireRole(user({ role: "owner" }), "maintainer"));
  assert.throws(() => requireRole(user({ role: "viewer" }), "maintainer"), {
    message: "insufficient role",
  });

  const config = await readFile(new URL("../wrangler.jsonc", import.meta.url), "utf8");
  assert.match(config, /"CRABFLEET_DEV_LOGIN_ENABLED": "false"/);
});

test("trusted proxy automatic roles admit authenticated users without a global allowlist", async () => {
  const writes: string[] = [];
  const env = runtimeEnv(
    d1((sql, _parameters, kind) => {
      if (kind === "all" && /from "allow_entries"/i.test(sql)) return { results: [] };
      if (kind === "all" && /from "users"/i.test(sql)) return { results: [] };
      if (kind === "run" && /^insert into "users"/i.test(sql)) {
        writes.push(sql);
        return { changes: 1 };
      }
      throw new Error(`unexpected query: ${sql}`);
    }),
    { CRABFLEET_TRUSTED_PROXY_AUTO_ROLE: "maintainer" },
  );

  const authenticated = await requireUser(new Request("https://fleet.example/api/state"), env, {
    kind: "authenticated",
    identity: {
      subject: "proxy:operator@example.test",
      identity: "operator@example.test",
      login: null,
      email: "operator@example.test",
      name: "operator@example.test",
    },
  });

  assert.deepEqual(authenticated, {
    subject: "proxy:operator@example.test",
    login: null,
    email: "operator@example.test",
    name: "operator@example.test",
    role: "maintainer",
    allowed: true,
    teams: [],
  });
  assert.equal(writes.length, 1);
});

test("trusted proxy automatic roles fail closed on elevated or malformed values", async () => {
  assert.equal(trustedProxyAutomaticRole("viewer"), "viewer");
  assert.equal(trustedProxyAutomaticRole("maintainer"), "maintainer");
  for (const value of [undefined, "", "owner", "Maintainer", " maintainer "]) {
    assert.equal(trustedProxyAutomaticRole(value), null);
  }

  const env = runtimeEnv(
    d1((sql) => {
      assert.match(sql, /from "allow_entries"/i);
      return { results: [] };
    }),
    { CRABFLEET_TRUSTED_PROXY_AUTO_ROLE: "owner" },
  );
  await assert.rejects(
    requireUser(new Request("https://fleet.example/api/state"), env, {
      kind: "authenticated",
      identity: {
        subject: "proxy:operator@example.test",
        identity: "operator@example.test",
        login: null,
        email: "operator@example.test",
        name: "operator@example.test",
      },
    }),
    (error: unknown) =>
      error instanceof Error &&
      error.message === "trusted proxy automatic role is invalid" &&
      "status" in error &&
      error.status === 403,
  );
});

test("secret encryption round-trips with the configured key and fails closed", async () => {
  const env = runtimeEnv({} as D1Database, {
    CRABBOX_TOKEN_ENCRYPTION_KEY: "encryption-key",
  });
  const sealed = await sealSecret(env, "credential");
  assert.match(sealed ?? "", /^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/);
  assert.equal(await openSecret(env, sealed ?? ""), "credential");
  assert.equal(await openSecret(env, `${sealed}corrupt`), null);
  assert.equal(await sealSecret(runtimeEnv({} as D1Database), "credential"), null);
});

