function oauthDatabase(): D1Database {
  return {
    prepare(sql: string) {
      return {
        bind() {
          return {
            async all() {
              return {
                results: /from "allow_entries"/iu.test(sql)
                  ? [{ value: "@owner", role: "viewer" }]
                  : [],
                meta: { changes: 0 },
              };
            },
            async run() {
              return { meta: { changes: 1 } };
            },
          };
        },
      };
    },
  } as unknown as D1Database;
}

