test("native GitHub refresh shares a retryable deadline across requests and team pages", async (t) => {
  const env = {
    CRABBOX_TOKEN_ENCRYPTION_KEY: "native-refresh-test-key",
  } as RuntimeEnv;
  const ciphertext = await sealSecret(env, "github-fixture");
  const queries: string[] = [];
  env.DB = {
    prepare(sql: string) {
      queries.push(sql);
      return {
        bind() {
          return {
            async all() {
              assert.match(sql, /from "native_access_tokens" as "t"/);
              return {
                results: [
                  {
                    ...viewer,
                    allowed: 1,
                    teams: JSON.stringify(viewer.teams),
                    token_hash: "token-hash",
                    scope: nativeAccessScope,
                    expires_at: Date.now() + 60_000,
                    github_token_ciphertext: ciphertext,
                  },
                ],
                meta: { changes: 0 },
              };
            },
          };
        },
      };
    },
  } as unknown as D1Database;

  for (const stalledPath of ["/user", "/user/teams?per_page=100&page=2"]) {
    const deadline = new AbortController();
    const durations: number[] = [];
    const timeout = t.mock.method(AbortSignal, "timeout", (milliseconds: number) => {
      durations.push(milliseconds);
      return deadline.signal;
    });
    const paths: string[] = [];
    const service = createNativeAuthService(env, async (input, init) => {
      const url = new URL(String(input));
      const path = url.pathname + url.search;
      paths.push(path);
      assert.equal(init?.signal, deadline.signal);
      if (path === stalledPath) {
        return new Promise<Response>((_resolve, reject) => {
          deadline.signal.addEventListener("abort", () => reject(deadline.signal.reason), {
            once: true,
          });
          deadline.abort(new DOMException("Timed out", "TimeoutError"));
        });
      }
      if (url.pathname === "/user/teams") {
        return Response.json(
          stalledPath === "/user" ? [] : Array.from({ length: 100 }, () => ({ slug: "core" })),
        );
      }
      if (url.pathname === "/user/emails") return Response.json([]);
      if (url.pathname.includes("/memberships/")) return Response.json({ state: "active" });
      return Response.json({ id: 1, login: viewer.login, email: viewer.email, name: viewer.name });
    });

    await assert.rejects(
      service.authenticate(
        new Request("https://fleet.example/api/native/v1/session", {
          headers: { authorization: `Bearer ${"a".repeat(64)}` },
        }),
      ),
      { status: 503, message: "GitHub membership refresh failed; retry later" },
    );
    assert.deepEqual(durations, [10_000]);
    assert.ok(paths.includes(stalledPath));
    assert.equal(paths.length, stalledPath === "/user" ? 4 : 5);
    timeout.mock.restore();
  }
  assert.equal(queries.length, 2);
  assert.ok(queries.every((sql) => sql.startsWith("select ")));
});

test("native auth pruning removes expired credentials without a new device start", async () => {
  const unconsumed = harness();
  const pending = await unconsumed.service.start("Pending Mac", "192.0.2.1");
  const pendingLink = decodeURIComponent(
    new URL(pending.verificationUri).pathname.split("/").at(-1)!,
  );
  await unconsumed.service.approve(pendingLink, viewer, "github-token");
  assert.ok([...unconsumed.store.access.values()][0]?.githubTokenCiphertext);

  unconsumed.setNow(pending.expiresAt);
  await unconsumed.service.pruneExpired();

  assert.equal(unconsumed.store.devices.size, 0);
  assert.equal(unconsumed.store.access.size, 0);

  const consumed = harness();
  const started = await consumed.service.start("Connected Mac", "192.0.2.2");
  const linkCode = decodeURIComponent(new URL(started.verificationUri).pathname.split("/").at(-1)!);
  await consumed.service.approve(linkCode, viewer, "github-token");
  const exchanged = await consumed.service.poll(started.deviceCode);
  assert.equal(exchanged.kind, "authorized");
  if (exchanged.kind !== "authorized") return;
  const tokenHash = await sha256(exchanged.accessToken);

  consumed.setNow(started.expiresAt);
  await consumed.service.pruneExpired();

  assert.equal(consumed.store.devices.size, 0);
  assert.ok(consumed.store.access.get(tokenHash)?.githubTokenCiphertext);

  consumed.setNow(exchanged.expiresAt);
  await consumed.service.pruneExpired();
  assert.equal(consumed.store.access.size, 0);
});

test("D1 native pruning deletes abandoned grants before expired devices", async () => {
  const statements: Array<{ sql: string; parameters: unknown[] }> = [];
  const database = {
    prepare(sql: string) {
      return {
        bind(...parameters: unknown[]) {
          return { sql, parameters };
        },
      };
    },
    async batch(values: Array<{ sql: string; parameters: unknown[] }>) {
      statements.push(...values);
      return [];
    },
  } as unknown as D1Database;

  await createNativeAuthService({ DB: database } as RuntimeEnv).pruneExpired(123_456);

  assert.equal(statements.length, 3);
  const sql = statements.map((statement) => statement.sql.replace(/\s+/gu, " ").toLowerCase());
  assert.match(
    sql[0] ?? "",
    /delete from native_access_tokens where token_hash in \( select access_token_hash from native_device_authorizations where expires_at <= \? and consumed_at is null and access_token_hash is not null \)/,
  );
  assert.match(sql[1] ?? "", /delete from "native_device_authorizations"/);
  assert.match(sql[2] ?? "", /delete from "native_access_tokens"/);
  assert.deepEqual(
    statements.map((statement) => statement.parameters),
    [[123_456], [123_456], [123_456]],
  );
});

function hasStatus(expected: number): (error: unknown) => boolean {
  return (error) => httpStatus(error) === expected;
}

function httpStatus(error: unknown): number | undefined {
  return typeof error === "object" && error && "status" in error ? Number(error.status) : undefined;
}

package rfb

import (
	"bytes"
	"testing"
)

func TestVNCChallengeResponseMatchesVendoredForkVectors(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name      string
		challenge []byte
		answer    string
		response  []byte
	}{
		{
			name:      "sequential",
			challenge: sequence(16),
			answer:    "12345678",
			response: []byte{
				0x83, 0xdd, 0x2b, 0x4d, 0xbd, 0x04, 0x36, 0x7f,
				0x28, 0x57, 0x8f, 0xdd, 0x5b, 0x14, 0x27, 0x40,
			},
		},
		{
			name:      "all ones short password",
			challenge: bytes.Repeat([]byte{0xff}, 16),
			answer:    "abc",
			response: []byte{
				0xe3, 0x21, 0xa7, 0xec, 0xc5, 0x47, 0xe6, 0x5b,
				0xe3, 0x21, 0xa7, 0xec, 0xc5, 0x47, 0xe6, 0x5b,
			},
		},
		{
			name:      "direct listener token",
			challenge: sequence(16),
			answer:    forkFixturePassword(),
			response: []byte{
				0x8a, 0x5f, 0xa9, 0x58, 0xf0, 0xd8, 0x19, 0xbd,
				0xcb, 0x98, 0x1c, 0x9b, 0x47, 0x63, 0x6e, 0xd0,
			},
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			response, err := VNCChallengeResponse(test.challenge, test.answer)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(response, test.response) {
				t.Fatalf("response = %x, want %x", response, test.response)
			}
			accepted, err := VerifyVNCResponse(test.challenge, response, test.answer)
			if err != nil || !accepted {
				t.Fatalf("verify = %v, %v", accepted, err)
			}
		})
	}
}

func forkFixturePassword() string {
	return "test-" + "auth-" + "token"
}

func TestVNCChallengeResponseRejectsMalformedInput(t *testing.T) {
	t.Parallel()
	if _, err := VNCChallengeResponse(make([]byte, 15), "password"); err == nil {
		t.Fatal("accepted short challenge")
	}
	if _, err := VNCChallengeResponse(make([]byte, 16), "snowman-☃"); err == nil {
		t.Fatal("accepted non-Latin-1 password")
	}
}

import assert from "node:assert/strict";
import test from "node:test";

import { api, DEFAULT_FETCH_TIMEOUT_MS } from "../src/app/api.js";

test("browser API aborts stalled requests after the default deadline", async (t) => {
  const timeout = AbortSignal.timeout;
  const durations: number[] = [];
  t.mock.method(AbortSignal, "timeout", (duration: number) => {
    durations.push(duration);
    return timeout(10);
  });
  t.mock.method(globalThis, "fetch", async (_path: string, options: RequestInit) => {
    const signal = options.signal!;
    return new Promise((_resolve, reject) => {
      signal.addEventListener("abort", () => reject(signal.reason), { once: true });
    });
  });
  // Keep the event loop alive while AbortSignal's unreferenced timer runs.
  const watchdog = setTimeout(() => {}, 1000);
  try {
    await assert.rejects(api("/api/fleet"), { name: "TimeoutError" });
    assert.deepEqual(durations, [DEFAULT_FETCH_TIMEOUT_MS]);
    assert.equal(DEFAULT_FETCH_TIMEOUT_MS, 30_000);
  } finally {
    clearTimeout(watchdog);
  }
});

test("browser API preserves caller cancellation and request options", async (t) => {
  const controller = new AbortController();
  const body = JSON.stringify({ value: "@test-person", role: "viewer" });
  t.mock.method(AbortSignal, "timeout", () => {
    assert.fail("a caller signal must replace the default deadline");
  });
  t.mock.method(globalThis, "fetch", async (path: string, options: RequestInit) => {
    assert.equal(path, "/api/admin/allow");
    assert.equal(options.method, "POST");
    assert.equal(options.body, body);
    assert.deepEqual(options.headers, {
      "content-type": "application/json",
      accept: "application/json",
    });
    assert.equal(options.signal, controller.signal);
    return new Promise((_resolve, reject) => {
      options.signal!.addEventListener("abort", () => reject(options.signal!.reason), {
        once: true,
      });
    });
  });
  const pending = api("/api/admin/allow", {
    method: "POST",
    body,
    headers: { accept: "application/json" },
    signal: controller.signal,
  });
  controller.abort();
  await assert.rejects(pending, { name: "AbortError" });
});

