window.WebSocket = class extends EventTarget {
  static OPEN = 1;
  static CLOSING = 2;
  readyState = 0;

  constructor(url) {
    super();
    this.host = decodeURIComponent(new URL(url).pathname.split("/")[3]);
    state.sockets.push(this);
    queueMicrotask(() => {
      this.readyState = 1;
      this.dispatchEvent(new Event("open"));
    });
  }

  send() {}

  close() {
    this.readyState = 3;
    this.dispatchEvent(new CloseEvent("close"));
  }
};

Object.defineProperty(navigator, "clipboard", {
  value: {
    readText: () => request("read", state.clients.at(-1).host),
    writeText: (text) => request("write", state.clients.at(-1).host, text),
  },
});

const createObjectURL = URL.createObjectURL.bind(URL);
URL.createObjectURL = (blob) => {
  state.exportedFiles++;
  return createObjectURL(blob);
};

const startInterval = window.setInterval.bind(window);
const stopInterval = window.clearInterval.bind(window);
window.setInterval = (callback, delay) => {
  const timer = startInterval(callback, delay);
  state.intervals.add(timer);
  return timer;
};
window.clearInterval = (timer) => {
  state.intervals.delete(timer);
  stopInterval(timer);
};

const createBitmap = window.createImageBitmap.bind(window);
window.createImageBitmap = (...args) => {
  const pending = state.nextBitmap;
  state.nextBitmap = null;
  return pending ? pending.promise : createBitmap(...args);
};

const rootEntries = [
  { name: "First", isDirectory: true, size: 0 },
  { name: "Second", isDirectory: true, size: 0 },
  { name: "example.txt", isDirectory: false, size: 12 },
];

function client(host) {
  const result = state.clients.find((entry) => entry.host === host);
  if (!result) throw new Error(`No fixture client for ${host}`);
  return result;
}

async function complete({ kind, host = "first", path, value, error }) {
  const pending = state.requests.find(
    (entry) =>
      !entry.settled &&
      entry.kind === kind &&
      entry.host === host &&
      (path === undefined || entry.path === path),
  );
  if (!pending) throw new Error(`No pending ${kind} for ${host}: ${path ?? "any path"}`);
  pending.settled = true;
  await act(async () => {
    if (error) pending.reject(new Error(error));
    else pending.resolve(kind === "download" ? new Blob(["Synthetic file"]) : value);
    await Promise.resolve();
  });
}

export const viewerTest = {
  async connect(host, media = false) {
    state.media = media;
    state.nextReady = deferred();
    await act(() =>
      render(
        <DesktopViewer host={{ id: host, name: `Desktop ${host}` }} onExit={() => {}} />,
        document.getElementById("app"),
      ),
    );
    await state.nextReady.promise;
    await complete({ kind: "list", host, path: "", value: rootEntries });
  },

  complete,

  pending(kind) {
    return state.requests
      .filter((entry) => !entry.settled && entry.kind === kind)
      .map(({ host, path }) => ({ host, path }));
  },

  summary() {
    return {
      exportedFiles: state.exportedFiles,
      uploads: state.requests.filter((entry) => entry.kind === "upload").length,
      quality: state.clients.at(-1)?.quality,
      closedMedia:
        state.players.every((player) => player.closed) &&
        state.decoders.every((decoder) => decoder.closed),
      closedSockets: state.sockets.every((socket) => socket.readyState === 3),
      activeIntervals: state.intervals.size,
      players: state.players.map(({ closed, muted }) => ({ closed, muted })),
    };
  },

  receiveClipboard(host, text) {
    void client(host).callbacks.onClipboard(text);
  },

  async fail(host) {
    await act(async () => {
      client(host).finished.reject(new Error("Synthetic connection failed"));
      await Promise.resolve();
    });
  },

  async beginFrame(host, name, color) {
    const surface = new OffscreenCanvas(8, 8);
    const context = surface.getContext("2d");
    context.fillStyle = color;
    context.fillRect(0, 0, 8, 8);
    const bitmap = await createBitmap(surface);
    const close = bitmap.close.bind(bitmap);
    const frame = { bitmap, pending: deferred(), closed: false };
    bitmap.close = () => {
      frame.closed = true;
      close();
    };
    state.nextBitmap = frame.pending;
    frame.completion = client(host).callbacks.onFrame({
      encoding: "jpeg",
      payload: new Uint8Array(),
    });
    state.frames.set(name, frame);
  },

  async finishFrame(name) {
    const frame = state.frames.get(name);
    frame.pending.resolve(frame.bitmap);
    await act(async () => await frame.completion);
    const canvas = document.querySelector("canvas");
    return {
      closed: frame.closed,
      pixel: [
        ...canvas.getContext("2d").getImageData(canvas.width / 2, canvas.height / 2, 1, 1).data,
      ],
    };
  },
};

window.viewerTest = viewerTest;

// Local browser test fixture: generated pixels and silent audio only.
export class BrowserHost {
  constructor() {
    this.rtc = new RTCPeerConnection({ iceServers: [], bundlePolicy: "max-bundle" });
    this.signals = [];
    this.candidates = [];
    this.received = [];
    this.streams = [];
    this.opened = false;
    this.closed = false;
    this.rtc.onicecandidate = ({ candidate }) => {
      if (candidate) this.signals.push({ candidate: candidate.toJSON() });
    };
    this.rtc.ondatachannel = ({ channel }) => {
      if (channel.label !== "rtc" || this.channel) throw new Error("Unexpected test channel");
      this.channel = channel;
      channel.binaryType = "arraybuffer";
      channel.onopen = () => {
        this.opened = true;
      };
      channel.onmessage = ({ data }) => {
        const bytes = new Uint8Array(data);
        if (this.received.length + bytes.length > 1024 * 1024) {
          this.close();
          throw new Error("Test control limit exceeded");
        }
        for (const byte of bytes) this.received.push(byte);
        channel.send(data);
      };
    };
    this.deadline = setTimeout(() => this.close(), 60000);
  }

  async accept(kind, sdp) {
    await this.rtc.setRemoteDescription({ type: kind, sdp });
    for (const candidate of this.candidates.splice(0)) await this.rtc.addIceCandidate(candidate);
    if (kind === "offer") {
      await this.rtc.setLocalDescription(await this.rtc.createAnswer());
      this.signals.push({ description: this.rtc.localDescription.toJSON() });
    }
  }

  async candidate(candidate, index, mid) {
    const value = { candidate, sdpMLineIndex: index, sdpMid: mid || null };
    if (this.rtc.remoteDescription) await this.rtc.addIceCandidate(value);
    else this.candidates.push(value);
  }

  takeSignals() {
    return this.signals.splice(0);
  }
  receivedBytes() {
    return Uint8Array.from(this.received);
  }

  async addMedia() {
    const canvas = document.createElement("canvas");
    canvas.width = 320;
    canvas.height = 180;
    const paint = () => {
      const context = canvas.getContext("2d");
      context.fillStyle = "#ff0000";
      context.fillRect(0, 0, 320, 180);
    };
    paint();
    this.videoTimer = setInterval(paint, 50);
    const video = canvas.captureStream(15);
    this.streams.push(video);
    this.rtc.addTrack(video.getVideoTracks()[0], video);

    this.audio = new AudioContext({ sampleRate: 48000 });
    const destination = this.audio.createMediaStreamDestination();
    const oscillator = this.audio.createOscillator();
    const gain = this.audio.createGain();
    gain.gain.value = 0;
    oscillator.connect(gain).connect(destination);
    oscillator.start();
    this.oscillator = oscillator;
    this.streams.push(destination.stream);
    this.rtc.addTrack(destination.stream.getAudioTracks()[0], destination.stream);

    // Exercise normal browser activation instead of disabling autoplay policy.
    await new Promise((resolve, reject) => {
      const button = document.createElement("button");
      button.id = "start-synthetic-audio";
      button.textContent = "Start silent WebRTC test audio";
      document.body.append(button);
      this.audioButton = button;
      const timer = setTimeout(() => {
        button.remove();
        reject(new Error("Test audio gesture timed out"));
      }, 30000);
      button.onclick = () => {
        this.audio.resume().then(() => {
          clearTimeout(timer);
          button.remove();
          resolve();
        }, reject);
      };
    });
    await this.rtc.setLocalDescription(await this.rtc.createOffer());
    this.signals.push({ description: this.rtc.localDescription.toJSON() });
  }

  async close() {
    if (this.closed) return;
    this.closed = true;
    clearTimeout(this.deadline);
    clearInterval(this.videoTimer);
    this.audioButton?.remove();
    this.channel?.close();
    this.rtc.close();
    this.oscillator?.stop();
    for (const stream of this.streams) for (const track of stream.getTracks()) track.stop();
    if (this.audio) await this.audio.close();
  }
}

export function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function decodedAudio(rtc) {
  let samples = 0;
  const stats = await rtc.getStats();
  for (const value of stats.values()) {
    if (value.type === "inbound-rtp" && value.kind === "audio") {
      const codec = stats.get(value.codecId);
      if (codec?.mimeType?.toLowerCase() === "audio/opus")
        samples += value.totalSamplesReceived || 0;
    }
  }
  return samples;
}

export function tracksStopped(stream) {
  return stream.getTracks().every((track) => track.readyState === "ended");
}

