    ) -> Result<JsValue, JsValue>;
    #[wasm_bindgen(method, js_name = takeSignals)]
    fn take_signals(this: &BrowserHost) -> js_sys::Array;
    #[wasm_bindgen(method, js_name = receivedBytes)]
    fn received_bytes(this: &BrowserHost) -> js_sys::Uint8Array;
